const cx0 = Number(entrada?.obsCentralX ?? 0);
const cy0 = Number(entrada?.obsCentralY ?? 0);
const r0 = Number(entrada?.obsRadio ?? 14);

const obstaculos = [
  { x: cx0, y: cy0, r: r0 },
  { x: -20, y: -10, r: 9 },
  { x: 22, y: 11, r: 10 }
];
const margen = 1.2;

const ruta = [
  { x: -45, y: -25 },
  { x: vars.x1, y: vars.y1 },
  { x: vars.x2, y: vars.y2 },
  { x: vars.x3, y: vars.y3 },
  { x: vars.x4, y: vars.y4 },
  { x: 45, y: 25 }
];

let distancia = 0.0;
let violacion = 0.0;

for (let i = 0; i < ruta.length - 1; i++) {
  const A = ruta[i];
  const B = ruta[i + 1];
  const dx = B.x - A.x;
  const dy = B.y - A.y;
  const lenSq = dx * dx + dy * dy;
  distancia += Math.sqrt(lenSq);

  for (const obs of obstaculos) {
    const t = lenSq > 1e-9
      ? Math.max(0.0, Math.min(1.0, ((obs.x - A.x) * dx + (obs.y - A.y) * dy) / lenSq))
      : 0.0;
    const px = A.x + t * dx;
    const py = A.y + t * dy;
    const dist = Math.hypot(px - obs.x, py - obs.y);
    if (dist < obs.r + margen) {
      violacion += (obs.r + margen - dist);
    }
  }
}

// Costo de giro: penaliza quiebres bruscos entre segmentos consecutivos
let costoGiro = 0.0;
for (let i = 1; i < ruta.length - 1; i++) {
  const v1x = ruta[i].x - ruta[i - 1].x;
  const v1y = ruta[i].y - ruta[i - 1].y;
  const v2x = ruta[i + 1].x - ruta[i].x;
  const v2y = ruta[i + 1].y - ruta[i].y;
  const n1 = Math.hypot(v1x, v1y);
  const n2 = Math.hypot(v2x, v2y);
  if (n1 > 1e-6 && n2 > 1e-6) {
    const cosAng = Math.max(-1.0, Math.min(1.0, (v1x * v2x + v1y * v2y) / (n1 * n2)));
    costoGiro += (1.0 - cosAng) * 50.0;
  }
}

return {
  fitness: [distancia, Math.max(0.1, costoGiro)],
  violacion,
  escena: {
    xlim: [-55, 55],
    ylim: [-38, 38],
    grid: true,
    titulo: violacion > 0
      ? `Colisión (${violacion.toFixed(1)} u) | Dist: ${distancia.toFixed(1)}`
      : `Ruta segura: ${distancia.toFixed(1)} u | Giro: ${costoGiro.toFixed(1)}`,
    circulos: obstaculos.map((o, idx) => ({
      x: o.x,
      y: o.y,
      r: o.r,
      relleno: idx === 0 ? "rgba(239, 68, 68, 0.28)" : "rgba(249, 115, 22, 0.22)",
      borde: idx === 0 ? "#ef4444" : "#f97316",
      grosor: 2
    })),
    curvas: [
      { puntos: ruta, color: violacion > 0 ? "#f43f5e" : "#22c55e", grosor: 3 }
    ],
    puntos: [
      { x: -45, y: -25, r: 5.5, color: "#38bdf8", etiqueta: "Origen" },
      ...ruta.slice(1, -1).map((p, idx) => ({ x: p.x, y: p.y, r: 4, color: "#facc15", etiqueta: `W${idx + 1}` })),
      { x: 45, y: 25, r: 5.5, color: "#a78bfa", etiqueta: "Destino" }
    ]
  }
};
